'use strict';

// SQ-213, package 1 of docs/superpowers/specs/literature-note-design.md: local
// extraction and a validated printed-page map. The fixtures are invented PDFs,
// generated by test/fixtures/literature-note/make-fixtures.py with the standard
// library; no publisher text is involved.
//
// The assertions here are the named ones from the design's package 1: a regular
// offset binds the map to the PDF bytes, an irregular offset refuses without a
// confirmed map, missing or ambiguous labels are not printed-page authority,
// blank pages preserve physical indices, repeated body text is not removed as a
// header, changed PDF or map invalidates evidence, and missing extraction tools
// report a dependency failure.

const test = require('node:test');
const assert = require('node:assert/strict');
const childProcess = require('node:child_process');
const crypto = require('node:crypto');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

const pluginRoot = path.resolve(__dirname, '..');
const script = path.join(pluginRoot, 'scripts', 'extract-paper.py');
const fixtures = path.join(__dirname, 'fixtures', 'literature-note');

const scratch = () => fs.mkdtempSync(path.join(os.tmpdir(), 'rh-literature-'));
const readJson = (file) => JSON.parse(fs.readFileSync(file, 'utf8'));
const sha256 = (file) => crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex');
const pdf = (name) => path.join(fixtures, name);

// `python3` is the extraction entry point; if it is missing the spawn itself
// reports it, and a missing tool must not read as a passing check.
function extract(args, options = {}) {
  const out = childProcess.spawnSync(process.env.PYTHON || 'python3', [script, ...args], {
    cwd: options.cwd || fixtures,
    encoding: 'utf8',
    env: options.env || process.env,
  });
  if (out.error) assert.fail(`python3 could not be started: ${out.error.message}`);
  return out;
}

const sidecarOf = (dir, name) => readJson(path.join(dir, `${name}.page-map.json`));
const lines = (text) => text.split('\n').map((line) => line.trim());

test('regular printed labels bind the map to PDF bytes', () => {
  const out = scratch();
  const run = extract([pdf('regular.pdf'), '--offset', '40', '--out', out]);
  assert.equal(run.status, 0, run.stdout + run.stderr);

  const sidecar = sidecarOf(out, 'regular');
  assert.equal(sidecar.schema, 'literature-note/page-map@1');
  assert.equal(sidecar.physicalPages, 3);
  assert.equal(sidecar.mapping.method, 'offset');
  assert.equal(sidecar.mapping.offset, 40);
  assert.deepEqual(sidecar.pages.map((page) => page.physical), [1, 2, 3]);
  assert.deepEqual(sidecar.pages.map((page) => page.printed), [41, 42, 43]);
  assert.deepEqual(sidecar.pages.map((page) => page.printedSource), ['offset', 'offset', 'offset']);
  assert.deepEqual(sidecar.pages.map((page) => page.label.bands), [['footer'], ['footer'], ['footer']]);
  assert.equal(sidecar.pdfSha256, sha256(pdf('regular.pdf')), 'the map is not bound to the PDF bytes');
  assert.equal(
    sidecar.extractionSha256,
    sha256(path.join(out, 'regular.full.txt')),
    'the map is not bound to the extraction bytes'
  );

  // The full extraction keeps the raw headers and every physical page boundary.
  const full = fs.readFileSync(path.join(out, 'regular.full.txt'), 'utf8');
  assert.equal(full.split('\f').length, 3, 'the extraction is not three physical pages');
  assert.match(full, /Invented Journal of Organization Studies 12 \(3\)/);
  assert.ok(lines(full.split('\f')[0]).includes('41'), 'the raw footer label is missing from the full extraction');
});

test('irregular offsets refuse without a confirmed map', () => {
  const out = scratch();
  const refused = extract([pdf('irregular.pdf'), '--offset', '40', '--out', out]);
  assert.equal(refused.status, 3, refused.stdout + refused.stderr);
  assert.match(refused.stderr, /constant offset/);
  assert.match(refused.stderr, /1 -> 41, 2 -> 43, 3 -> 44/);
  assert.ok(
    !fs.existsSync(path.join(out, 'irregular.page-map.json')),
    'a refused run still wrote a page map'
  );

  const confirmed = extract([pdf('irregular.pdf'), '--map', pdf('irregular.confirmed-map.json'), '--out', out]);
  assert.equal(confirmed.status, 0, confirmed.stdout + confirmed.stderr);
  const sidecar = sidecarOf(out, 'irregular');
  assert.equal(sidecar.mapping.method, 'confirmed-map');
  assert.deepEqual(sidecar.pages.map((page) => page.printed), [41, 43, 44]);
  assert.equal(sidecar.mapping.confirmedBy, 'A. Researcher');
  assert.equal(sidecar.mapping.mapSha256, sha256(pdf('irregular.confirmed-map.json')));
  assert.deepEqual(
    sidecar.pages.map((page) => page.agreesWithLabel),
    [true, true, true],
    'the confirmed map disagrees with the labels on the page',
  );
});

test('missing or ambiguous labels are not printed-page authority', () => {
  const missing = extract([pdf('missing-label.pdf'), '--offset', '40', '--out', scratch()]);
  assert.equal(missing.status, 3, missing.stdout + missing.stderr);
  assert.match(missing.stderr, /physical page 3 carries no page-number label/);

  const ambiguous = extract([pdf('ambiguous-label.pdf'), '--offset', '40', '--out', scratch()]);
  assert.equal(ambiguous.status, 3, ambiguous.stdout + ambiguous.stderr);
  assert.match(ambiguous.stderr, /physical page 1 .*ambiguous/);
  assert.match(ambiguous.stderr, /\[12, 41\]/);

  // Without a candidate offset the extractor still runs, records what it saw
  // and claims no printed page: a label is a candidate, never authority.
  const out = scratch();
  const observed = extract([pdf('ambiguous-label.pdf'), '--out', out]);
  assert.equal(observed.status, 0, observed.stdout + observed.stderr);
  const sidecar = sidecarOf(out, 'ambiguous-label');
  assert.equal(sidecar.mapping.method, 'none');
  assert.deepEqual(sidecar.pages.map((page) => page.printed), [null, null, null]);
  assert.deepEqual(sidecar.pages.map((page) => page.labelProblem), ['ambiguous', 'ambiguous', 'ambiguous']);
  assert.deepEqual(sidecar.pages[0].label.candidates, [12, 41]);
});

test('blank pages preserve physical indices', () => {
  const out = scratch();
  const plain = extract([pdf('blank-page.pdf'), '--out', out]);
  assert.equal(plain.status, 0, plain.stdout + plain.stderr);
  assert.match(plain.stderr, /physical page\(s\) \[2\] carry no extractable text/);

  const sidecar = sidecarOf(out, 'blank-page');
  assert.equal(sidecar.physicalPages, 3, 'the empty middle page was dropped or the trailing form feed was kept');
  assert.deepEqual(sidecar.pages.map((page) => page.hasText), [true, false, true]);
  assert.deepEqual(sidecar.uncheckablePages, [2]);
  assert.equal(fs.readFileSync(path.join(out, 'blank-page.full.txt'), 'utf8').split('\f').length, 3);

  // A page without text carries no label, so automatic numbering refuses it.
  const refused = extract([pdf('blank-page.pdf'), '--offset', '40', '--out', out]);
  assert.equal(refused.status, 3, refused.stdout + refused.stderr);
  assert.match(refused.stderr, /physical page 2 carries no page-number label/);

  // The confirmed map may name that page as explicitly unnumbered.
  const confirmed = extract([pdf('blank-page.pdf'), '--map', pdf('blank-page.confirmed-map.json'), '--out', out]);
  assert.equal(confirmed.status, 0, confirmed.stdout + confirmed.stderr);
  const mapped = sidecarOf(out, 'blank-page');
  assert.deepEqual(mapped.pages.map((page) => page.printed), [41, null, 43]);
  assert.equal(mapped.pages[1].printedSource, null);
  assert.deepEqual(mapped.pages.map((page) => page.physical), [1, 2, 3], 'the pages after the blank one shifted');
});

test('repeated body text is not removed as a header', () => {
  const out = scratch();
  const run = extract([pdf('repeated-body.pdf'), '--offset', '40', '--out', out]);
  assert.equal(run.status, 0, run.stdout + run.stderr);

  const sentence = 'We thank the reviewers of this invented journal for their careful reading.';
  const full = fs.readFileSync(path.join(out, 'repeated-body.full.txt'), 'utf8');
  const view = fs.readFileSync(path.join(out, 'repeated-body.request.txt'), 'utf8');
  assert.equal(full.split(sentence).length - 1, 3, 'the full extraction lost a repeated body line');
  assert.equal(view.split(sentence).length - 1, 3, 'a repeated body line was removed as a header');

  // Only identified furniture leaves the request view: the banner, the label
  // lines it matched, and the references section.
  const sidecar = sidecarOf(out, 'repeated-body');
  assert.deepEqual(sidecar.omittedFromRequest, { bannerLines: 1, labelLines: 2, referenceLines: 6 });
  assert.doesNotMatch(view, /Downloaded from example\.invalid/);
  assert.doesNotMatch(view, /Cordell, R\./);
  assert.ok(!lines(view.split('\f')[0]).includes('41'), 'the identified page-number label stayed in the request view');
  assert.equal(view.split('\f').length, 3, 'the request view lost the physical page boundaries');
  assert.equal(sidecar.requestLossy, true);
  assert.equal(sidecar.requestSha256, sha256(path.join(out, 'repeated-body.request.txt')));
});

test('changed PDF or map invalidates evidence', () => {
  const work = scratch();
  const map = path.join(work, 'map.json');
  fs.copyFileSync(pdf('irregular.confirmed-map.json'), map);

  const first = extract([pdf('irregular.pdf'), '--map', map, '--out', work]);
  assert.equal(first.status, 0, first.stdout + first.stderr);
  const sidecar = path.join(work, 'irregular.page-map.json');
  assert.equal(extract([pdf('irregular.pdf'), '--verify', sidecar]).status, 0, 'a fresh record did not verify');

  const otherPdf = extract([pdf('regular.pdf'), '--verify', sidecar]);
  assert.equal(otherPdf.status, 5, otherPdf.stdout + otherPdf.stderr);
  assert.match(otherPdf.stderr, /PDF bytes changed/);

  const editedMap = readJson(map);
  editedMap.pages[1].printed = 42;
  fs.writeFileSync(map, `${JSON.stringify(editedMap, null, 2)}\n`);
  const afterMap = extract([pdf('irregular.pdf'), '--verify', sidecar]);
  assert.equal(afterMap.status, 5, afterMap.stdout + afterMap.stderr);
  assert.match(afterMap.stderr, /confirmed page map changed/);

  fs.appendFileSync(path.join(work, 'irregular.full.txt'), '\nedited\n');
  const afterText = extract([pdf('irregular.pdf'), '--verify', sidecar]);
  assert.equal(afterText.status, 5, afterText.stdout + afterText.stderr);
  assert.match(afterText.stderr, /full extraction changed/);

  // A map bound to other bytes is refused, never applied to this PDF.
  const foreign = readJson(map);
  foreign.pdfSha256 = sha256(pdf('regular.pdf'));
  fs.writeFileSync(map, `${JSON.stringify(foreign, null, 2)}\n`);
  const unbound = extract([pdf('irregular.pdf'), '--map', map, '--out', scratch()]);
  assert.equal(unbound.status, 4, unbound.stdout + unbound.stderr);
  assert.match(unbound.stderr, /not bound to these PDF bytes/);
});

test('missing extraction tools report dependency failure', () => {
  const missing = extract([pdf('regular.pdf'), '--extractor', '/nonexistent/pdftotext', '--out', scratch()]);
  assert.equal(missing.status, 2, 'a missing pdftotext must not read as a passing check');
  assert.match(missing.stderr, /pdftotext is not available/);

  const found = extract([pdf('regular.pdf'), '--out', scratch()]);
  assert.equal(found.status, 0, 'the same PDF extracts with the installed pdftotext');
});
